package cl.nexbyte.siger.institucional.nucleo;

import cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales;
import cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales.FacultadCierre;
import cl.nexbyte.siger.institucional.nucleo.CatalogoLaboratorio.Operador;
import cl.nexbyte.siger.institucional.robustez.*;
import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;
import tools.jackson.databind.json.JsonMapper;
import static cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.*;

/** SUB-CONT-01. Facultad por Caso: no agrega roles, pertenencias ni acceso documental. */
public final class RevisionExcepcional {
    public record Solicitar(long revision,String revisor,Instant desde,Instant hasta,String fundamento,List<UUID> documentos){@Override public String toString(){return "SolicitudRevisionExcepcional[reservada]";}}
    public record Decidir(long revision,String fundamento){}
    public record Confirmar(long revision,long revisionCaso,String huellaAntecedentes,boolean confirmacionRevision,String fundamento){}
    private final BaseJdbc db;private final NucleoInstitucional core;private final CatalogoLaboratorio cat;private final AutoridadesInstitucionales autoridad;private final Clock clock;private final JsonMapper json;private final PoliticaAreas areas;
    RevisionExcepcional(BaseJdbc db,NucleoInstitucional core,CatalogoLaboratorio cat,AutoridadesInstitucionales autoridad,Clock clock,JsonMapper json){this.db=db;this.core=core;this.cat=cat;this.autoridad=autoridad;this.clock=clock;this.json=json;areas=new PoliticaAreas(db,clock);}
    private static String s(Map<String,Object> row,String key){return row.get(key)==null?null:row.get(key).toString();}
    private static long n(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
    private static UUID u(Object id){return UUID.fromString(id.toString());}
    private String hash(Object value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(value)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
    private String persona(String actor){if(autoridad==null)throw new FalloTecnico(409,"IDENTIDAD_INSTITUCIONAL_NO_ACREDITADA");return autoridad.contextoCierre(actor).persona();}
    private void motivo(String v){try{cl.nexbyte.siger.contrato.DeclaracionNna.texto(v==null?null:v.replace('\n',' ').replace('\r',' '),2000,true);}catch(IllegalArgumentException e){throw new FalloTecnico(400);}}
    private static void version(Map<String,Object> e,long r){if(r<0||n(e,"revision")!=r)throw new FalloTecnico(409,"VERSION_OBSOLETA");}
    private Map<String,Object> fila(UUID id){var rows=db.sql.queryForList("SELECT * FROM institution_closure_exception WHERE id=?",id.toString());if(rows.isEmpty())throw new FalloTecnico(404);var e=rows.getFirst();String sealed=hash(Arrays.asList(e.get("case_id"),e.get("closure_request"),e.get("requested_by"),e.get("requested_person"),e.get("reviewer_id"),e.get("reviewer_person"),e.get("unit_code"),e.get("site_id"),e.get("area_id"),e.get("matter_id"),e.get("requested_ms"),e.get("from_ms"),e.get("until_ms"),e.get("reason_text"),e.get("documents_doc")));if(!sealed.equals(e.get("request_hash")))throw new FalloTecnico(409,"INSTRUCCION_ALTERADA");return e;}
    private boolean cubre(FacultadCierre f,Map<String,Object> c){return f.estado().equals("ACTIVA")&&!f.desde().isAfter(clock.instant())&&f.hasta().isAfter(clock.instant())&&f.unidad().equals(c.get("unit_code"))&&f.sede().equals(c.get("site_id"))&&Objects.equals(f.area(),areas.area(c))&&Objects.equals(f.materia(),new PoliticaMaterias(db,clock).materia(u(c.get("id"))));}
    private FacultadCierre facultad(String actor,Map<String,Object> c){if(autoridad==null)throw new FalloTecnico(409,"AUTORIDAD_CIERRE_NO_ACREDITADA");var ctx=autoridad.contextoCierre(actor);return ctx.facultades().stream().filter(f->f.persona().equals(ctx.persona())&&cubre(f,c)).findFirst().orElseThrow(()->new FalloTecnico(404));}
    private void solicitante(Operador a,Map<String,Object> c){core.autorizarCaso(a,u(c.get("id")));if(!a.id().equals(c.get("responsible_id"))||!a.profesionalEn(s(c,"unit_code"),s(c,"site_id"),areas.area(c)))throw new FalloTecnico(404);persona(a.id());}
    private String solicitudCierre(UUID cas){var rows=db.sql.queryForList("SELECT id,at_ms FROM core_review WHERE case_id=? AND decision='SOLICITUD_TERMINO' ORDER BY at_ms DESC,id DESC LIMIT 2",cas.toString());if(rows.isEmpty())throw new FalloTecnico(409,"CIERRE_REQUIERE_SOLICITUD_ACTUAL");if(rows.size()>1&&Objects.equals(rows.getFirst().get("at_ms"),rows.get(1).get("at_ms")))throw new FalloTecnico(409,"SOLICITUD_CIERRE_AMBIGUA");return s(rows.getFirst(),"id");}
    private List<String> propios(UUID cas){return db.sql.queryForList("SELECT document_id FROM management_document_link WHERE case_id=? UNION SELECT document_id FROM document_content_policy WHERE owner_case=?",cas.toString(),cas.toString()).stream().map(r->s(r,"document_id")).filter(doc->!cl.nexbyte.siger.institucional.documental.AsociacionesVigentes.retiradaCaso(db,cas,UUID.fromString(doc))).sorted().toList();}
    private List<String> documentos(Map<String,Object> e){return Arrays.asList(json.readValue(s(e,"documents_doc"),String[].class));}
    private String antecedentes(Operador a,Map<String,Object> e){UUID cas=u(e.get("case_id"));core.autorizarConsultaCaso(a,cas);var ids=new TreeSet<>(documentos(e));ids.addAll(propios(cas));var rows=new ArrayList<Object>();for(String id:ids){var p=core.contenidos().permisos(a,cas,u(id));if(!p.contenido()||!p.clasificacion().equals("ORDINARIO")&&!p.clasificacion().equals("FIR"))throw new FalloTecnico(409,"ANTECEDENTES_REQUIEREN_PERMISO_ESPECIFICO");var doc=db.sql.queryForMap("SELECT sha256 FROM institution_document WHERE id=?",id);var policy=db.sql.queryForList("SELECT revision,classification FROM document_content_policy WHERE document_id=?",id);rows.add(Arrays.asList(id,doc.get("sha256"),policy));}return hash(rows);}
    private void contextoActual(Map<String,Object> e,Map<String,Object> c){if(!core.casoU2(u(c.get("id")))||!"REVISION_TERMINO".equals(c.get("state"))||!Objects.equals(c.get("responsible_id"),e.get("requested_by"))||!persona(s(e,"requested_by")).equals(e.get("requested_person"))||!Objects.equals(c.get("unit_code"),e.get("unit_code"))||!Objects.equals(c.get("site_id"),e.get("site_id"))||!Objects.equals(areas.area(c),e.get("area_id"))||!Objects.equals(new PoliticaMaterias(db,clock).materia(u(c.get("id"))),e.get("matter_id"))||!solicitudCierre(u(c.get("id"))).equals(e.get("closure_request")))throw new FalloTecnico(409,"SOLICITUD_OBSOLETA");}
    private void independiente(String p,Map<String,Object> e){if(p.equals(e.get("requested_person"))||p.equals(e.get("reviewer_person")))throw new FalloTecnico(403,"SEPARACION_DE_FUNCIONES_REQUERIDA");}
    private void historia(Operador a,UUID id,Map<String,Object> c,String code,String reason){core.u2().historia(u(c.get("communication_id")),id,"REV_CIERRE",n(fila(id),"revision"),a,code,reason,Map.of("caso",c.get("id")));}
    public Resultado solicitar(Operador a,UUID key,UUID cas,Solicitar r){return intento(a,cas,"SOLICITAR",()->solicitarValidada(a,key,cas,r));}
    private Resultado solicitarValidada(Operador a,UUID key,UUID cas,Solicitar r){if(r==null||r.revisor()==null||r.desde()==null||r.hasta()==null||!r.hasta().isAfter(r.desde())||!r.hasta().isAfter(clock.instant()))throw new FalloTecnico(400);motivo(r.fundamento());var initial=core.caseRow(cas);solicitante(a,initial);
        return core.execute(key,a,"SOLICITAR_REVISION_EXCEPCIONAL",List.of(cas,r),()->{core.lock(u(initial.get("communication_id")));var c=core.caseRow(cas);solicitante(a,c);version(c,r.revision());if(!core.casoU2(cas)||!"REVISION_TERMINO".equals(c.get("state")))throw new FalloTecnico(409,"CIERRE_REQUIERE_SOLICITUD_ACTUAL");if(!autoridad.subrogancias().casoPropioSubrogante(a.id(),s(c,"unit_code"),s(c,"site_id"),areas.area(c)))throw new FalloTecnico(403,"CONTINUIDAD_REQUIERE_SUBROGANCIA_ACREDITADA");String requested=persona(a.id()),reviewer=persona(r.revisor());if(requested.equals(reviewer))throw new FalloTecnico(403,"SEPARACION_DE_FUNCIONES_REQUERIDA");
            if(autoridad.contextoCierre(a.id()).facultades().stream().noneMatch(f->cubre(f,c)))throw new FalloTecnico(409,"AUTORIDAD_CIERRE_NO_ACREDITADA");
            if(db.sql.queryForObject("SELECT COUNT(*) FROM institution_closure_exception WHERE case_id=? AND state IN ('PENDIENTE','HABILITADA') AND until_ms>?",Long.class,cas.toString(),clock.millis())>0)throw new FalloTecnico(409,"REVISION_EXCEPCIONAL_PENDIENTE");
            var docs=new TreeSet<>(propios(cas));if(r.documentos()!=null){if(r.documentos().size()>500||r.documentos().stream().anyMatch(Objects::isNull))throw new FalloTecnico(400);r.documentos().forEach(d->docs.add(d.toString()));}String doc=json.writeValueAsString(docs);var probe=new LinkedHashMap<String,Object>();probe.put("case_id",cas.toString());probe.put("documents_doc",doc);antecedentes(a,probe);antecedentes(cat.operador(r.revisor()),probe);
            String closure=solicitudCierre(cas),matter=new PoliticaMaterias(db,clock).materia(cas);long at=clock.millis();var values=Arrays.asList(cas.toString(),closure,a.id(),requested,r.revisor(),reviewer,c.get("unit_code"),c.get("site_id"),areas.area(c),matter,at,r.desde().toEpochMilli(),r.hasta().toEpochMilli(),r.fundamento(),doc);UUID id=UUID.randomUUID();var args=new ArrayList<Object>();args.add(id.toString());args.addAll(values);args.add(hash(values));db.sql.update("INSERT INTO institution_closure_exception(id,case_id,closure_request,requested_by,requested_person,reviewer_id,reviewer_person,unit_code,site_id,area_id,matter_id,requested_ms,from_ms,until_ms,reason_text,documents_doc,request_hash,state,revision) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'PENDIENTE',0)",args.toArray());historia(a,id,c,"CIERRE_EXCEPCION_SOLICITADA",r.fundamento());return new Resultado(id,0);
        });
    }
    private FacultadCierre autorizar(Operador a,Map<String,Object> e){var f=facultad(a.id(),core.caseRow(u(e.get("case_id"))));independiente(persona(a.id()),e);return f;}
    public Resultado decidir(Operador a,UUID key,UUID id,Decidir r,String action){return intento(a,id,action,()->decidirValidada(a,key,id,r,action));}
    private Resultado decidirValidada(Operador a,UUID key,UUID id,Decidir r,String action){if(r==null||!Set.of("APROBAR","RECHAZAR","REVOCAR","RETIRAR").contains(action))throw new FalloTecnico(400);motivo(r.fundamento());var e=fila(id);if(action.equals("RETIRAR"))solicitante(a,core.caseRow(u(e.get("case_id"))));else autorizar(a,e);
        return core.execute(key,a,"REVISION_EXCEP_"+action,List.of(id,r),()->{var row=fila(id);var c=core.caseRow(u(row.get("case_id")));core.lock(u(c.get("communication_id")));row=fila(id);c=core.caseRow(u(row.get("case_id")));if(action.equals("RETIRAR"))solicitante(a,c);else autorizar(a,row);version(row,r.revision());
            if(action.equals("APROBAR")||action.equals("RECHAZAR")){if(!row.get("state").equals("PENDIENTE"))throw new FalloTecnico(409);if(action.equals("APROBAR")){contextoActual(row,c);var f=autorizar(a,row);if(n(row,"until_ms")<=clock.millis()||n(row,"from_ms")<f.desde().toEpochMilli()||n(row,"until_ms")>f.hasta().toEpochMilli())throw new FalloTecnico(409,"APROBACION_NO_VIGENTE");antecedentes(cat.operador(s(row,"reviewer_id")),row);db.sql.update("UPDATE institution_closure_exception SET state='HABILITADA',revision=revision+1,authorized_by=?,authorized_person=?,authorized_ms=?,capability_id=?,capability_hash=?,authority_revision=?,basis_ref=?,basis_sha256=?,decision_text=? WHERE id=?",a.id(),persona(a.id()),clock.millis(),f.id(),hash(f),autoridad.contextoCierre(a.id()).revision(),f.referencia(),f.sha256(),r.fundamento(),id.toString());}
                else db.sql.update("UPDATE institution_closure_exception SET state='RECHAZADA',revision=revision+1,ended_by=?,ended_ms=?,end_reason=? WHERE id=?",a.id(),clock.millis(),r.fundamento(),id.toString());
            }else{if(action.equals("RETIRAR")?!row.get("state").equals("PENDIENTE"):!Set.of("PENDIENTE","HABILITADA").contains(row.get("state")))throw new FalloTecnico(409);db.sql.update("UPDATE institution_closure_exception SET state=?,revision=revision+1,ended_by=?,ended_ms=?,end_reason=? WHERE id=?",action.equals("RETIRAR")?"RETIRADA":"REVOCADA",a.id(),clock.millis(),r.fundamento(),id.toString());}
            historia(a,id,c,"CIERRE_EXCEPCION_"+action,r.fundamento());return new Resultado(id,r.revision()+1);
        });
    }
    void revisor(Operador a,UUID id){var e=fila(id);if(!a.id().equals(e.get("reviewer_id"))||!persona(a.id()).equals(e.get("reviewer_person"))||persona(a.id()).equals(e.get("requested_person")))throw new FalloTecnico(404);core.autorizarConsultaCaso(a,u(e.get("case_id")));}
    void validar(Operador a,UUID id,Confirmar r,UUID esperado){revisor(a,id);var e=fila(id);if(!esperado.toString().equals(e.get("case_id")))throw new FalloTecnico(404);var c=core.caseRow(u(e.get("case_id")));version(e,r.revision());contextoActual(e,c);if(!r.confirmacionRevision()||!e.get("state").equals("HABILITADA")||n(e,"from_ms")>clock.millis()||n(e,"until_ms")<=clock.millis())throw new FalloTecnico(409,"APROBACION_NO_VIGENTE");autorizar(cat.operador(s(e,"authorized_by")),e);var f=autoridad.contextoCierre(s(e,"authorized_by")).facultades().stream().filter(cap->cap.id().equals(e.get("capability_id"))&&cap.persona().equals(e.get("authorized_person"))&&cubre(cap,c)).findFirst().orElseThrow(()->new FalloTecnico(409,"APROBACION_NO_VIGENTE"));if(!hash(f).equals(e.get("capability_hash"))||!persona(s(e,"authorized_by")).equals(e.get("authorized_person")))throw new FalloTecnico(409,"APROBACION_NO_VIGENTE");if(!antecedentes(a,e).equals(r.huellaAntecedentes()))throw new FalloTecnico(409,"ANTECEDENTES_MODIFICADOS");}
    void consumir(Operador a,UUID id,String motivo){db.sql.update("UPDATE institution_closure_exception SET state='UTILIZADA',revision=revision+1,ended_by=?,ended_ms=? WHERE id=?",a.id(),clock.millis(),id.toString());historia(a,id,core.caseRow(u(fila(id).get("case_id"))),"CIERRE_EXCEPCION_UTILIZADA",motivo);}
    public Resultado confirmar(Operador a,UUID key,UUID id,Confirmar r){return intento(a,id,"CONFIRMAR",()->confirmarValidada(a,key,id,r));}
    private Resultado confirmarValidada(Operador a,UUID key,UUID id,Confirmar r){if(r==null)throw new FalloTecnico(400);motivo(r.fundamento());revisor(a,id);return core.cierreExcepcional(a,key,u(fila(id).get("case_id")),new Decision(r.revisionCaso(),r.fundamento()),id,r);}
    private boolean visible(Operador a,Map<String,Object> e){String p=persona(a.id());if(p.equals(e.get("requested_person"))||p.equals(e.get("reviewer_person")))try{core.autorizarConsultaCaso(a,u(e.get("case_id")));return true;}catch(FalloTecnico ex){if(!Set.of(401,403,404,409).contains(ex.status))throw ex;}try{autorizar(a,e);return true;}catch(FalloTecnico ex){if(Set.of(401,403,404,409).contains(ex.status))return false;throw ex;}}
    private void temporales(){for(var e:db.sql.queryForList("SELECT * FROM institution_closure_exception WHERE state='HABILITADA' AND until_ms<=?",clock.millis())){db.sql.update("UPDATE institution_closure_exception SET state='EXPIRADA',revision=revision+1,ended_ms=? WHERE id=?",e.get("until_ms"),e.get("id"));db.sql.update("INSERT INTO authority_event(actor_id,resource_id,action_code,result_code,at_ms,snapshot_doc) VALUES(NULL,?,'CIERRE_EXCEP_EXPIRADA','VIGENCIA_TERMINADA',?,?)",e.get("id"),clock.millis(),json.writeValueAsString(Map.of("efectivaHasta",e.get("until_ms"),"registradaEn",clock.millis())));db.sql.update("INSERT INTO workflow_event(event_key,code,resource_type,resource_id,at_ms) VALUES(?,'CONTINUIDAD_DECIDIDA','REV_CIERRE',?,?)",e.get("id")+":"+(n(e,"revision")+1)+":EXPIRADA",e.get("id"),clock.millis());}}
    public List<Map<String,Object>> bandeja(Operador a){return db.transaction(()->{core.bloquearAcceso(a);temporales();var result=new ArrayList<Map<String,Object>>();for(var row:db.sql.queryForList("SELECT * FROM institution_closure_exception ORDER BY requested_ms DESC,id"))if(visible(a,row))result.add(vista(a,fila(u(row.get("id")))));return result;});}
    private Map<String,Object> vista(Operador a,Map<String,Object> e){var out=new LinkedHashMap<String,Object>();e.forEach((k,v)->out.put(k.toLowerCase(Locale.ROOT),v));out.remove("request_hash");out.put("puedeDecidir",false);try{autorizar(a,e);out.put("puedeDecidir",true);}catch(FalloTecnico ex){if(!Set.of(401,403,404,409).contains(ex.status))throw ex;}out.put("puedeConfirmar",false);try{var c=core.caseRow(u(e.get("case_id")));validar(a,u(e.get("id")),new Confirmar(n(e,"revision"),n(c,"revision"),antecedentes(a,e),true,"Consulta de habilitación"),u(c.get("id")));out.put("puedeConfirmar",true);}catch(FalloTecnico ex){if(!Set.of(401,403,404,409).contains(ex.status))throw ex;}out.put("historial",db.sql.queryForList("SELECT actor_id,at_ms,action_code,reason_text FROM institution_flow_history WHERE resource_id=? ORDER BY seq",e.get("id")).stream().map(row->{var normalized=new LinkedHashMap<String,Object>();row.forEach((k,v)->normalized.put(k.toLowerCase(Locale.ROOT),v));return normalized;}).toList());return out;}
    public Map<String,Object> paquete(Operador a,UUID id){return db.transaction(()->{core.bloquearAcceso(a);revisor(a,id);var e=fila(id);UUID cas=u(e.get("case_id"));String fingerprint=antecedentes(a,e);var c=core.caso(a,cas);if(!e.get("state").equals("UTILIZADA"))validar(a,id,new Confirmar(n(e,"revision"),c.revision(),fingerprint,true,"Consulta de revisión"),cas);db.sql.update("INSERT INTO authority_event(actor_id,resource_id,action_code,result_code,at_ms,snapshot_doc) VALUES(?,?,'CIERRE_EXCEP_CONSULTA','AUTORIZADA',?,NULL)",a.id(),id.toString(),clock.millis());return Map.of("instruccion",vista(a,e),"caso",c,"huellaAntecedentes",fingerprint,"bloqueos",Map.of("obligatorias",core.equipo().obligatorias(cas),"espera",core.equipo().esperaPendiente(cas),"derivacion",c.derivacionPendiente(),"terminoColaboracion",core.terminoColaboracion().pendienteCaso(cas)));});}
    public Map<String,Object> contexto(Operador a,UUID cas){return db.transaction(()->{core.bloquearAcceso(a);var c=core.caseRow(cas);core.autorizarConsultaCaso(a,cas);boolean own=a.id().equals(c.get("responsible_id"))&&a.profesionalEn(s(c,"unit_code"),s(c,"site_id"),areas.area(c));boolean enabled=own&&"REVISION_TERMINO".equals(c.get("state"))&&autoridad!=null&&autoridad.subrogancias().casoPropioSubrogante(a.id(),s(c,"unit_code"),s(c,"site_id"),areas.area(c))&&autoridad.contextoCierre(a.id()).facultades().stream().anyMatch(f->cubre(f,c));var eligible=new ArrayList<String>();if(enabled)for(var candidate:cat.operadores())try{if(!persona(candidate.id()).equals(persona(a.id()))){core.autorizarConsultaCaso(candidate,cas);eligible.add(candidate.id());}}catch(FalloTecnico ex){if(!Set.of(401,403,404,409).contains(ex.status))throw ex;}return Map.of("puedeSolicitar",enabled,"elegibles",eligible,"revision",n(c,"revision"),"documentos",propios(cas),"solicitudes",bandeja(a).stream().filter(e->e.get("case_id").equals(cas.toString())).toList());});}
    private Resultado intento(Operador a,UUID id,String action,java.util.function.Supplier<Resultado> work){try{return work.get();}catch(FalloTecnico e){if(Set.of(403,404,409).contains(e.status))db.transaction(()->{core.bloquearAcceso(a);db.sql.update("INSERT INTO authority_event(actor_id,resource_id,action_code,result_code,at_ms,snapshot_doc) VALUES(?,?,?,?,?,NULL)",a.id(),id.toString(),"CIERRE_EXCEP_"+action,"DENEGADO_"+e.status,clock.millis());return null;});throw e;}}
    public boolean autorizarAviso(Operador a,UUID id){try{return visible(a,fila(id));}catch(FalloTecnico e){if(Set.of(401,403,404,409).contains(e.status))return false;throw e;}}
}
